/* To-do list · style.css */

/* Step 3: the page and the card */
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 40px 16px;
  font-family: Arial, sans-serif;
  color: #1e1527;
  background-color: #f1e9f6;
}

.todo-app {
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  padding: 28px 24px;
  border-radius: 16px;
  background-color: #ffffff;
  box-shadow: 0 8px 24px rgba(67, 35, 95, 0.15);
}

h1 {
  margin: 0 0 20px;
  color: #43235f;
  font-size: 28px;
}

/* Step 4: the form to add tasks */
#todo-form {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 20px;
}

#todo-form label {
  width: 100%;
  font-size: 14px;
  font-weight: bold;
}

#todo-input {
  flex: 1;
  min-width: 0;
  padding: 12px;
  border: 2px solid #cfc8d8;
  border-radius: 8px;
  font-size: 16px;
}

#todo-input:focus {
  border-color: #602b7a;
  outline: 3px solid #e3d3ee;
}

#todo-form button {
  padding: 12px 20px;
  border: none;
  border-radius: 8px;
  background-color: #602b7a;
  color: #ffffff;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
}

#todo-form button:hover {
  background-color: #43235f;
}

/* Step 5: the list of tasks */
#todo-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

#todo-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  border-bottom: 1px solid #e7e1ee;
}

#todo-list label {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
}

#todo-list input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: #602b7a;
}

.done .task-text {
  color: #6b6177;
  text-decoration: line-through;
}

.delete {
  padding: 8px 12px;
  border: 2px solid #c62828;
  border-radius: 8px;
  background-color: #ffffff;
  color: #c62828;
  cursor: pointer;
}

.delete:hover {
  background-color: #c62828;
  color: #ffffff;
}

.counter {
  margin: 16px 0 0;
  color: #6b6177;
  font-size: 14px;
}

.storage-msg {
  margin: 8px 0 0;
  color: #8a4b00;
  font-size: 14px;
}

