// To-do list · script.js

// Step 6: the elements of the page and the list of tasks
const form = document.querySelector("#todo-form");
const input = document.querySelector("#todo-input");
const list = document.querySelector("#todo-list");
const counter = document.querySelector("#counter");
const storageMsg = document.querySelector("#storage-msg");

// Every task is an object with its text and whether it's done
let tasks = [
  { text: "Buy bread", done: false },
  { text: "Learn HTML", done: true },
];

// Step 10: count the tasks that are not done yet
function updateCounter() {
  let left = 0;
  for (const task of tasks) {
    if (!task.done) {
      left++;
    }
  }
  if (left === 1) {
    counter.textContent = "1 task left";
  } else {
    counter.textContent = left + " tasks left";
  }
}

// Step 11: save the tasks in the browser and load them again
const STORAGE_OFF = "Your tasks can't be saved in this browser: they will disappear if you reload the page.";

function save() {
  try {
    localStorage.setItem("todo-tasks", JSON.stringify(tasks));
  } catch (error) {
    storageMsg.textContent = STORAGE_OFF;
  }
}

function load() {
  try {
    const saved = localStorage.getItem("todo-tasks");
    if (saved !== null) {
      tasks = JSON.parse(saved);
    }
  } catch (error) {
    storageMsg.textContent = STORAGE_OFF;
  }
}

// Step 7: draw the list from the array
function render() {
  list.innerHTML = "";

  tasks.forEach((task, index) => {
    const item = document.createElement("li");
    if (task.done) {
      item.classList.add("done");
    }

    const label = document.createElement("label");
    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.checked = task.done;
    const text = document.createElement("span");
    text.className = "task-text";
    text.textContent = task.text;
    label.appendChild(checkbox);
    label.appendChild(text);

    const deleteButton = document.createElement("button");
    deleteButton.className = "delete";
    deleteButton.textContent = "Delete";

    item.appendChild(label);
    item.appendChild(deleteButton);
    list.appendChild(item);

    // Step 8: tick the box to complete a task (or untick it)
    checkbox.addEventListener("change", () => {
      task.done = checkbox.checked;
      render();
    });

    // Step 9: delete a task
    deleteButton.addEventListener("click", () => {
      tasks.splice(index, 1);
      render();
    });
  });

  updateCounter();
  save();
}

// Step 6: add a task when the form is sent
form.addEventListener("submit", (event) => {
  event.preventDefault();
  const text = input.value.trim();
  if (text === "") {
    return;
  }
  tasks.push({ text: text, done: false });
  console.log(tasks);
  render();
  input.value = "";
  input.focus();
});

// Step 11: load the saved tasks, then draw the list
load();
render();
